"""Manually authored claim decisions after reading the source passages.

The helper only serializes the explicitly supplied scientific judgments. It does
not infer claims, proof status or literature fate from headings or keywords.
"""
from pathlib import Path
import json,csv
B=Path(__file__).resolve().parents[1];O=B/'parts/root'
items={x['id']:x for x in json.loads((O/'items.json').read_text())}
claims=[];events=[]
WHO='GPT-6 Astra Pro / inherited effort (not numerically exposed) / SA18 root'
def C(n,status,cls,search,refs,fate,date,statement=None,proof=None,confidence='high',suffix='',words=None,scans=None,lines=None,origin='Grothendieck manuscript'):
    i=items[f'SA18-{n}'];cid=f'CL-SA18-{n}{suffix}'
    refs=refs.split() if isinstance(refs,str) else refs
    comp={'method':'No finite numerical calculation is asserted for this conceptual claim.'}
    if proof:comp={'proof_record':proof,'code':'scripts/root_certificates.py','output':'outputs/root_certificates.json','scope':'Exact finite algebra/model calculations where named; general arguments are in the proof record, not inferred from finite tests.'}
    claims.append(dict(id=cid,items=[i['id']],cote=i['cote'],scans=scans or i['scans'],lines=lines or i['lines'],
      his_statement=words or i['his_words'],statement=statement or i['statement'],status_on_pages=status,
      computation=comp,**{'class':cls},fate=fate,fate_date=date,
      present_status='As of 2026-11-19: '+fate,refs=refs,confidence=confidence,
      research_searches=[search],origin=origin))
    events.append(dict(statement_id=cid,date='2026-11-19',who=WHO,type='used and rechecked in this run',outcome='Read the source passage and matched exact scope to the opened references/search record '+search+'. '+status+'.'))
    if proof:events.append(dict(statement_id=cid,date='2026-11-19',who=WHO,type='targeted proof check',outcome=proof+'; finite certificates supplement, and do not replace, the stated general proof.'))
    return cid

